"use client";

import { useRouter } from "next/navigation";
import React from "react";
import axios from "axios";

import { UploadIcon } from "../../_icons/uplaod-icon";

const steps = [
  { number: 1, label: "Upload" },
  { number: 2, label: "Label" },
  { number: 3, label: "Train" },
];

type UploadItem = {
  id: string;
  name: string;
  preview: string;
  status: "uploading" | "done" | "error";
  url?: string;
  error?: string;
};

export default function Upload() {
  const router = useRouter();
  const fileInputRef = React.useRef<HTMLInputElement>(null);
  const [items, setItems] = React.useState<UploadItem[]>([]);
  const [dragging, setDragging] = React.useState(false);

  const updateItem = (id: string, patch: Partial<UploadItem>) =>
    setItems((prev) => prev.map((it) => (it.id === id ? { ...it, ...patch } : it)));

  const uploadFiles = async (fileList: FileList | File[]) => {
    const files = Array.from(fileList).filter((f) => f.type.startsWith("image/"));
    if (files.length === 0) return;

    const newItems: UploadItem[] = files.map((file) => ({
      id: crypto.randomUUID(),
      name: file.name,
      preview: URL.createObjectURL(file),
      status: "uploading",
    }));
    setItems((prev) => [...newItems, ...prev]);

    await Promise.all(
      files.map(async (file, i) => {
        const id = newItems[i].id;
        const formData = new FormData();
        formData.append("file", file);
        try {
          const { data } = await axios.post("/api/photos", formData);
          updateItem(id, { status: "done", url: data.photo.storagePath });
        } catch (err) {
          const message = axios.isAxiosError(err)
            ? (err.response?.data?.error ?? err.message)
            : "Upload failed";
          console.error("Error uploading photo:", message);
          updateItem(id, { status: "error", error: message });
        }
      }),
    );
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files) uploadFiles(event.target.files);
    event.target.value = ""; // allow re-selecting the same file
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragging(false);
    uploadFiles(event.dataTransfer.files);
  };

  const uploading = items.some((it) => it.status === "uploading");
  const doneCount = items.filter((it) => it.status === "done").length;

  return (
    <div className="min-h-screen w-full bg-[var(--page-bg)] px-4 py-6 sm:px-6 lg:px-10">
      <div className="mx-auto max-w-5xl rounded-[24px] border border-[var(--surface-border)] bg-[var(--surface-card-strong)] p-5 shadow-sm sm:p-8">
        <header className="mb-8 flex flex-col gap-2">
          <p className="text-[12px] font-bold uppercase tracking-[0.12em] text-[var(--primary)] sm:text-[13px]">
            part 3 · training ground
          </p>
          <h1 className="font-display text-[30px] leading-tight tracking-[-0.03em] text-[var(--text)] sm:text-[40px]">
            Upload training images
          </h1>
        </header>

        {/* Stepper */}
        <ol className="mb-8 flex w-full max-w-xl items-center">
          {steps.map((step, index) => {
            const isActive = index === 0;
            return (
              <li key={step.number} className="flex flex-1 items-center last:flex-none">
                <div className="flex flex-col items-center gap-2">
                  <div
                    className={[
                      "flex h-11 w-11 items-center justify-center rounded-full text-sm font-extrabold sm:h-12 sm:w-12 sm:text-base",
                      isActive
                        ? "bg-[var(--primary)] text-white"
                        : "border-2 border-[var(--surface-border)] bg-[var(--surface-card)] text-[var(--muted)]",
                    ].join(" ")}>
                    {step.number}
                  </div>
                  <span
                    className={[
                      "text-[11px] font-bold uppercase tracking-[0.08em]",
                      isActive ? "text-[var(--text)]" : "text-[var(--muted)]",
                    ].join(" ")}>
                    {step.label}
                  </span>
                </div>
                {index < steps.length - 1 && (
                  <div className="mx-2 mb-6 h-[2px] flex-1 bg-[var(--surface-border)]" />
                )}
              </li>
            );
          })}
        </ol>

        {/* Drop zone */}
        <div
          role="button"
          tabIndex={0}
          onClick={() => fileInputRef.current?.click()}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") fileInputRef.current?.click();
          }}
          onDragOver={(e) => {
            e.preventDefault();
            setDragging(true);
          }}
          onDragLeave={() => setDragging(false)}
          onDrop={handleDrop}
          className={[
            "flex min-h-[240px] cursor-pointer flex-col items-center justify-center rounded-[20px] border-[3px] border-dashed px-5 py-8 text-center transition-colors sm:min-h-[280px]",
            dragging
              ? "border-[var(--primary)] bg-[var(--info-bg)]"
              : "border-[var(--surface-dashed)] bg-[var(--surface-card)] hover:border-[var(--primary)] hover:bg-[var(--info-bg)]",
          ].join(" ")}>
          <input
            ref={fileInputRef}
            type="file"
            onChange={handleFileChange}
            accept="image/*"
            multiple
            className="hidden"
          />
          <div className="mb-5 inline-flex h-16 w-16 items-center justify-center rounded-full bg-[var(--info-bg)] text-[var(--primary)]">
            <UploadIcon />
          </div>
          <h2 className="font-display text-[22px] leading-none tracking-[-0.03em] text-[var(--text)] sm:text-[26px]">
            Upload your photos
          </h2>
          <p className="mt-3 max-w-md text-[15px] text-[var(--muted)] sm:text-[17px]">
            Click or drag &amp; drop cat images here to begin training.
          </p>
        </div>

        {/* Uploaded previews */}
        {items.length > 0 && (
          <section className="mt-6">
            <p className="mb-3 text-[14px] font-bold text-[var(--muted)]">
              {doneCount} of {items.length} uploaded
            </p>
            <ul className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
              {items.map((it) => (
                <li
                  key={it.id}
                  className="relative overflow-hidden rounded-[12px] border border-[var(--surface-border)] bg-[var(--surface-card)]">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={it.url ?? it.preview}
                    alt={it.name}
                    className={[
                      "aspect-square w-full object-cover",
                      it.status === "uploading" ? "opacity-50" : "",
                    ].join(" ")}
                  />
                  <span
                    className={[
                      "absolute left-2 top-2 rounded-full px-2 py-0.5 text-[11px] font-bold text-white",
                      it.status === "done"
                        ? "bg-green-600"
                        : it.status === "error"
                          ? "bg-red-600"
                          : "bg-[var(--primary)]",
                    ].join(" ")}>
                    {it.status === "done" ? "Saved" : it.status === "error" ? "Failed" : "Uploading…"}
                  </span>
                  {it.error && (
                    <p className="px-2 py-1 text-[11px] leading-tight text-red-600">{it.error}</p>
                  )}
                </li>
              ))}
            </ul>
          </section>
        )}

        <div className="mt-6 rounded-[12px] bg-[var(--info-bg)] px-5 py-4 text-[15px] text-[var(--text)]">
          <span className="font-extrabold text-[var(--primary)]">Tip:</span> Use
          clear, well-lit images to help the model learn faster.
        </div>

        <div className="mt-6 flex justify-end">
          <button
            type="button"
            onClick={() => router.push("/label")}
            disabled={uploading || doneCount === 0}
            className="inline-flex items-center justify-center rounded-[12px] bg-[var(--primary)] px-6 py-3 text-[16px] font-extrabold text-white transition-colors hover:bg-[var(--primary-hover)] disabled:cursor-not-allowed disabled:opacity-50">
            {uploading ? "Uploading…" : "Next: Label photos"}
          </button>
        </div>
      </div>
    </div>
  );
}
